'use strict';
(()=>{
const C=window.REFLEJO,KEY='ludaria_reflejo_diseno_v1',$=id=>document.getElementById(id),N=C.pages.length;
const fresh=()=>({version:1,page:0,visited:[0],reviewed:[],caseChoices:{},revealed:false,fields:{evidence:'',caution:'',agreement1:'',agreement2:'',agreement3:'',ownEvidence:''}});
let state=fresh(),storageOK=true,opener=null,toastTimer;
try{const s=JSON.parse(localStorage.getItem(KEY)||'null');if(s?.version===1){state.page=Number.isInteger(s.page)&&s.page>=0&&s.page<N?s.page:0;state.visited=Array.isArray(s.visited)?[...new Set(s.visited.filter(n=>n>=0&&n<N))]:[0];state.reviewed=Array.isArray(s.reviewed)?s.reviewed.filter(id=>C.rubric.some(r=>r.id===id)):[];for(const r of C.rubric)if(['inicial','desarrollo','logrado'].includes(s.caseChoices?.[r.id]))state.caseChoices[r.id]=s.caseChoices[r.id];state.revealed=s.revealed===true;for(const k of Object.keys(state.fields))if(typeof s.fields?.[k]==='string')state.fields[k]=s.fields[k].slice(0,5000);}}catch(e){storageOK=false;}
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch(e){storageOK=false;}}
const b=(action,text,attrs='',secondary=false)=>`<button class="button ${secondary?'secondary':''}" data-action="${action}" ${attrs}>${text}</button>`;
const t=(action,text,attrs='')=>`<button class="text-button" data-action="${action}" ${attrs}>${text}</button>`;
const field=(id,label,placeholder='',rows=3)=>`<label class="field" for="field-${id}">${label}<textarea id="field-${id}" data-field="${id}" maxlength="5000" rows="${rows}" placeholder="${esc(placeholder)}">${esc(state.fields[id])}</textarea></label>`;
const title=n=>`<div class="section-title"><div><span class="eyebrow">SANTUARIO DEL ESPEJO · MIRA · EVALUACIÓN</span><h2>${C.pages[n].title}</h2></div><span class="time-label">${C.pages[n].time} min · en clase</span></div><p class="lead">${C.pages[n].prompt}</p>`;
const scene=(n,body)=>`<section class="scene"><div class="scene-content wide">${title(n)}${body}<p class="note product">Producto: ${C.pages[n].product}</p></div></section>`;
const labels={inicial:'Inicial',desarrollo:'En desarrollo',logrado:'Logrado'};
function criterionCard(r,i){return `<button class="mirror-card ${state.reviewed.includes(r.id)?'reviewed':''}" data-action="criterion" data-id="${r.id}"><span class="num">0${i+1}</span><h3>${r.name}</h3><p>${r.question}</p></button>`;}
function rubricTable(current=''){return `<div class="rubric-scroll"><table class="rubric-table"><thead><tr><th>Criterio</th><th>Inicial</th><th>En desarrollo</th><th>Logrado</th></tr></thead><tbody>${C.rubric.map(r=>`<tr class="${r.id===current?'current':''}"><td><strong>${r.name}</strong></td><td>${r.levels.inicial}</td><td>${r.levels.desarrollo}</td><td>${r.levels.logrado}</td></tr>`).join('')}</tbody></table></div>`;}
function focusPage(n,r){return scene(n,`<div class="criteria-focus"><div><span class="eyebrow">PREGUNTA DE EVIDENCIA</span><blockquote>${r.question}</blockquote><div class="evidence-list">${r.evidence.map(x=>`<span>${x}</span>`).join('')}</div><p class="note"><strong>Cautela:</strong> ${r.caution}</p></div><div class="level-grid">${Object.entries(r.levels).map(([k,v])=>`<article class="level-card"><span class="eyebrow">${labels[k]}</span><p>${v}</p></article>`).join('')}</div></div><div class="actions">${t('criterion','Abrir la ficha completa',`data-id="${r.id}"`)}${t('sources','Fuentes y alcance')}</div>`);}
function caseRows(){return C.rubric.map(r=>`<div class="case-row"><strong>${r.name}</strong>${Object.keys(labels).map(k=>`<button data-action="case-choice" data-id="${r.id}" data-level="${k}" aria-pressed="${state.caseChoices[r.id]===k}">${labels[k]}</button>`).join('')}</div>`).join('');}
function caseFeedback(){if(!state.revealed)return'';return `<div class="case-feedback"><strong>Lectura propuesta para conversar — no es una calificación automática.</strong>${C.rubric.map(r=>`<p><b>${r.name}: ${labels[C.caseModel.proposed[r.id]]}.</b> ${C.caseModel.reasons[r.id]}</p>`).join('')}</div>`;}
function page(n){switch(n){
case 0:return `<section class="scene"><div class="cover-content"><span class="eyebrow">MISIÓN PRINCIPAL · MÓDULO 4 · SESIÓN 11</span><h1 class="cover-title">El Reflejo<br>del <span>Diseño</span></h1><p class="lead">Cinco caras devuelven una pregunta:<br>¿qué evidencia sostiene nuestro juicio?</p><div class="cover-meta"><span class="small-line"></span><span>Santuario del Espejo · Guardiana Mira</span></div><div class="actions">${b('begin','Cruzar el umbral')}</div><p class="note">90 minutos sincrónicos · 45 autónomos · Evaluación</p></div></section>`;
case 1:return scene(n,`<div class="three-column"><article class="panel"><span class="eyebrow">CRITERIO</span><h3>La pregunta común</h3><p>Define qué aspecto observamos; evita valorar desde preferencias cambiantes.</p></article><article class="panel"><span class="eyebrow">EVIDENCIA</span><h3>La huella localizable</h3><p>Señala dónde aparece una decisión o una ausencia en el diseño.</p></article><article class="panel"><span class="eyebrow">ARGUMENTO</span><h3>La relación explícita</h3><p>Explica por qué esa evidencia corresponde al descriptor elegido.</p></article></div><p class="note">La rúbrica orienta una interpretación profesional. No sustituye el diálogo ni produce resultados por sí sola.</p>`);
case 2:return scene(n,`<div class="pyramid" aria-label="Relación entre niveles del diseño"><div class="p1"><span class="eyebrow">PROPÓSITO</span><strong>Aprendizaje que orienta decisiones</strong></div><div class="p2"><span class="eyebrow">DINÁMICAS</span><strong>Experiencia y relaciones buscadas</strong></div><div class="p3"><span class="eyebrow">MECÁNICAS → COMPONENTES</span><strong>Reglas de actuación y formas visibles</strong></div></div><p class="note">La pirámide ayuda a preguntar si las partes funcionan como sistema. No es una escala de calidad ni demuestra eficacia educativa.</p><div class="actions">${t('sources','Leer referencia y límites')}</div>`);
case 3:return scene(n,`<div class="mirror-grid">${C.rubric.map(criterionCard).join('')}</div><p class="note">Los descriptores del Anexo E están disponibles íntegros en cada ficha y en la tabla general. Tres niveles, sin puntos ni pesos.</p><div class="actions">${t('rubric','Abrir la rúbrica completa')}</div>`);
case 4:return focusPage(n,C.rubric[0]);case 5:return focusPage(n,C.rubric[1]);case 6:return focusPage(n,C.rubric[2]);case 7:return focusPage(n,C.rubric[3]);case 8:return focusPage(n,C.rubric[4]);
case 9:return scene(n,`<div class="case-reflection"><article class="case-panel"><span class="eyebrow">${C.caseModel.title}</span><h3>Caso ficticio</h3><p>${C.caseModel.summary}</p><p class="note">${C.caseModel.note}</p></article><div><div class="case-controls">${caseRows()}</div><div class="actions">${b('reveal',state.revealed?'Ocultar lectura propuesta':'Contrastar con lectura propuesta')}${t('reset-case','Reiniciar decisiones')}</div>${caseFeedback()}</div></div>`);
case 10:return scene(n,`<p class="note">No buscamos uniformidad automática. Cuando dos lecturas difieren, volved al mismo criterio, localizad evidencia y explicitad el argumento.</p><div class="agreement-grid">${field('agreement1','Acuerdo 1 · Qué evidencia consideraremos suficiente','Ej.: citaremos una regla concreta y su efecto esperado, no solo el nombre del componente.')}${field('agreement2','Acuerdo 2 · Cómo trataremos los casos entre niveles','Ej.: registraremos el descriptor que mejor representa el conjunto y explicaremos la evidencia contradictoria.')}${field('agreement3','Acuerdo 3 · Qué inferencias evitaremos','Ej.: no inferiremos motivación real solo desde una intención de diseño.')}${field('ownEvidence','Una duda que debe seguir abierta','Anota una discrepancia que requiera más evidencia o conversación.')}</div><div class="actions">${b('notebook','Conservar los acuerdos')}${t('rubric','Revisar la rúbrica')}</div>`);
case 11:return scene(n,`<div class="split"><article class="download-card"><span class="eyebrow">45 MINUTOS AUTÓNOMOS</span><h3>Reunir evidencias del prototipo</h3><p>Localiza objetivos, narrativa y progresión, reglas, componentes, decisiones motivacionales y riesgos éticos. Señala dónde se encuentra cada evidencia.</p><p class="note">Preparación operativa para la autoevaluación de la sesión 12. Dedica 45 minutos a reunir las evidencias antes de valorar tu prototipo.</p><div class="actions">${b('notebook','Abrir mi registro')}${b('download','Descargar TXT','',true)}</div></article><div><span class="eyebrow">EL ESPEJO NO DICTA</span><h3 class="ceremony-title">Hace visible<br>cómo argumentamos.</h3><p class="lead">En El Pulido del Prototipo aplicarás la rúbrica a tu propio diseño y construirás un plan de mejora.</p><p class="note">El HTML guarda borradores en este dispositivo. No envía respuestas ni califica textos abiertos.</p></div></div>`);
}}
function render(focus=false){document.body.classList.toggle('is-cover',state.page===0);$('stage').innerHTML=page(state.page);$('page-count').textContent=`${state.page+1} / ${N}`;$('previous').disabled=state.page===0;$('next-label').textContent=state.page===N-1?'Mi registro':'Siguiente';$('route-dots').innerHTML=C.pages.map((p,i)=>`<button class="route-dot ${state.visited.includes(i)?'visited':''} ${i===state.page?'current':''}" data-action="go" data-page="${i}" aria-label="Pantalla ${i+1}: ${p.title}" ${i===state.page?'aria-current="step"':''}></button>`).join('');$('seal-status').innerHTML=C.rubric.map((r,i)=>`<button class="seal-dot ${state.reviewed.includes(r.id)?'solved':'pending'}" data-action="criterion" data-id="${r.id}" aria-label="${r.name}: ${state.reviewed.includes(r.id)?'revisado':'por revisar'}">${i+1}</button>`).join('');if(focus)$('stage').focus({preventScroll:true});}
function go(n){if(!Number.isInteger(n)||n<0||n>=N)return;if($('modal').open)$('modal').close();state.page=n;if(!state.visited.includes(n))state.visited.push(n);save();history.replaceState(null,'',`#pantalla-${n+1}`);render(true);window.scrollTo({top:0,behavior:'instant'});}
function modal(h,body){if(!$('modal').open)opener=document.activeElement;$('modal-body').innerHTML=`<h2 id="modal-title" tabindex="-1">${h}</h2>${body}`;if(!$('modal').open)$('modal').showModal();$('modal-title').focus({preventScroll:true});}
function close(){const old=opener;$('modal').close();render();if(old?.isConnected)old.focus({preventScroll:true});}
function toast(msg){clearTimeout(toastTimer);$('toast').textContent=msg;$('toast').hidden=false;toastTimer=setTimeout(()=>$('toast').hidden=true,3500);}
function criterion(id){const r=C.rubric.find(x=>x.id===id);if(!r)return;if(!state.reviewed.includes(id))state.reviewed.push(id);save();modal(r.name,`<p><strong>Pregunta de evidencia:</strong> ${r.question}</p><div class="level-grid">${Object.entries(r.levels).map(([k,v])=>`<article class="level-card"><span class="eyebrow">${labels[k]}</span><p>${v}</p></article>`).join('')}</div><div class="evidence-list">${r.evidence.map(x=>`<span>${x}</span>`).join('')}</div><p class="note"><strong>Cautela:</strong> ${r.caution}</p>`);}
function textRecord(){return ['BUSCADORES DE LA GAMIFICACIÓN PERDIDA','El Reflejo del Diseño · Sesión 11 · Misión principal · Módulo 4','Fecha: '+new Date().toLocaleDateString('es-CL'),'','APLICACIÓN AL CASO FICTICIO',...C.rubric.flatMap(r=>[r.name+': '+(labels[state.caseChoices[r.id]]||'Sin decisión'),state.revealed?'Lectura propuesta: '+labels[C.caseModel.proposed[r.id]]+' — '+C.caseModel.reasons[r.id]:'Lectura propuesta: no consultada','']),'ACUERDOS DE INTERPRETACIÓN',state.fields.agreement1||'(Sin registro)',state.fields.agreement2||'(Sin registro)',state.fields.agreement3||'(Sin registro)','','DUDA ABIERTA',state.fields.ownEvidence||'(Sin registro)','','EVIDENCIAS POR REUNIR PARA LA SESIÓN 12','Objetivos; narrativa y progresión; reglas; componentes; decisiones motivacionales y riesgos éticos.','','Registro local: no se ha enviado ni calificado desde este HTML.','','FUENTES',...C.sources.map(s=>s.apa)].join('\n');}
function notebook(){modal('Cuaderno del Espejo',`<p>Conserva aquí los acuerdos construidos en la clase. Requieren interpretación y revisión humanas.</p><div class="agreement-grid">${field('agreement1','Acuerdo 1')}${field('agreement2','Acuerdo 2')}${field('agreement3','Acuerdo 3')}${field('ownEvidence','Duda abierta')}</div><label class="field" for="export-text">Registro completo<textarea id="export-text" readonly rows="10">${esc(textRecord())}</textarea></label><div class="actions">${b('copy','Copiar registro')}${b('download','Descargar TXT','',true)}</div><p class="note">${storageOK?'Guardado local disponible.':'El marco restringe el guardado: copia el registro visible.'} No hay envío automático.</p>`);}
function sources(){modal('Fuentes y alcance',C.sources.map(s=>`<h3>${s.title}</h3><p>${esc(s.apa)}</p><p class="note">${esc(s.use)}</p>${s.url?`<p><a href="${s.url}" target="_blank" rel="noopener noreferrer">Consultar fuente</a></p>`:''}`).join('')+'<p class="note">Caso, preguntas de evidencia, secuencia y acuerdos: elaboración didáctica propia. Paisaje generado para Ludaria; diagrama y rúbrica construidos con código.</p>');}
async function download(){const blob=new Blob([textRecord()],{type:'text/plain;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='Registro_El_Reflejo_del_Diseno.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Registro preparado para descarga.');}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action;switch(a){
case'begin':go(1);break;case'go':go(Number(el.dataset.page));break;case'close':close();break;case'map':modal('Recorrido por el Santuario',`<p>Acceso libre a las ${N} pantallas. ${state.visited.length}/${N} visitadas en este dispositivo.</p><ol class="complete-list">${C.pages.map((p,i)=>`<li>${t('go',`${i+1}. ${p.title} · ${p.time} min.`,`data-page="${i}"`)}</li>`).join('')}</ol>`);break;
case'sources':sources();break;case'rubric':modal('Rúbrica de evaluación del proyecto',rubricTable()+'<p class="note">Anexo E de la tesis. Instrumento cualitativo: no se han añadido puntos, pesos ni promedios.</p>');break;case'criterion':criterion(el.dataset.id);break;
case'case-choice':state.caseChoices[el.dataset.id]=el.dataset.level;save();render();break;case'reveal':state.revealed=!state.revealed;save();render();break;case'reset-case':state.caseChoices={};state.revealed=false;save();render();break;case'notebook':notebook();break;case'download':download();break;case'copy':try{await navigator.clipboard.writeText(textRecord());toast('Registro copiado.');}catch(err){toast('Selecciona y copia el texto del registro.');}break;case'fullscreen':if(!document.fullscreenElement)document.documentElement.requestFullscreen?.();else document.exitFullscreen?.();break;}});
document.addEventListener('input',e=>{const f=e.target.dataset.field;if(f in state.fields){state.fields[f]=e.target.value.slice(0,5000);save();}});
$('previous').addEventListener('click',()=>go(state.page-1));$('next').addEventListener('click',()=>state.page===N-1?notebook():go(state.page+1));
$('modal').addEventListener('click',e=>{if(e.target===$('modal'))close();});document.addEventListener('keydown',e=>{if(e.key==='ArrowRight'&&!$('modal').open&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement?.tagName))go(state.page+1);if(e.key==='ArrowLeft'&&!$('modal').open&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement?.tagName))go(state.page-1);});
const hash=Number((location.hash.match(/pantalla-(\d+)/)||[])[1])-1;if(Number.isInteger(hash)&&hash>=0&&hash<N)state.page=hash;if(!state.visited.includes(state.page))state.visited.push(state.page);render();
})();

